import React, { useState, useEffect } from 'react';
import './App.css';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import { apiService } from './services/api.service';

export default function App() {
  const [session, setSession] = useState(() => apiService.getCurrentSession());
  const [currentView, setCurrentView] = useState('login');
  const [products, setProducts] = useState([]);

  useEffect(() => {
    if (session) {
      loadInventoryData();
    }
  }, [session]);

  const loadInventoryData = async () => {
    try {
      const data = await apiService.getInventory();
      setProducts(data);
    } catch (err) {
      console.error('Failed to load inventory data:', err);
    }
  };

  const handleLoginSuccess = (userData) => {
    setSession(userData);
  };

  const handleRegisterSuccess = (userData) => {
    setSession(userData);
  };

  const handleLogout = () => {
    apiService.logout();
    setSession(null);
    setCurrentView('login');
  };

  const handleAddProduct = async (newProduct) => {
    try {
      const updatedList = await apiService.addInventoryItem({
        productName: newProduct.name,
        category: newProduct.category,
        quantity: newProduct.quantity,
        unitPrice: newProduct.price,
        supplierName: newProduct.supplier
      });
      setProducts(updatedList);
    } catch (err) {
      alert(err.message);
    }
  };

  const handleDeleteProduct = async (id) => {
    try {
      const updatedList = await apiService.deleteInventoryItem(id);
      setProducts(updatedList);
    } catch (err) {
      alert(err.message);
    }
  };

  return (
    <>
      <div className="orb orb-1"></div>
      <div className="orb orb-2"></div>

      {!session ? (
        currentView === 'login' ? (
          <Login 
            onNavigate={setCurrentView} 
            onLoginSuccess={handleLoginSuccess} 
          />
        ) : (
          <Register 
            onNavigate={setCurrentView} 
            onRegisterSuccess={handleRegisterSuccess} 
          />
        )
      ) : (
        <Dashboard 
          user={session} 
          products={products}
          onLogout={handleLogout}
          onAddProduct={handleAddProduct}
          onDeleteProduct={handleDeleteProduct}
        />
      )}
    </>
  );
}
